            WHEN 'ETH' THEN 2 WHEN 'SOL' THEN 3 ELSE 4 END)*6+
            (CASE j.timeframe WHEN '1m' THEN 0 WHEN '5m' THEN 1 WHEN '15m' THEN 2
             WHEN '1h' THEN 3 WHEN '4h' THEN 4 ELSE 5 END);
